      const canvas = document.getElementById('canvas');
      const ctx = canvas.getContext('2d');
      const initialAngle = document.getElementById('initial-angle');
      const releaseButton = document.getElementById('release-button');
      let isReleased = false;
      let angle = parseFloat(initialAngle.value);
      let velocity = 0;
      let gravity = 0.0981; // acceleration due to gravity in m/s^2
      let radius = 100;
      let period = 2 * Math.PI * Math.sqrt(radius / gravity); // period of the pendulum

      function drawPendulum() {
        ctx.clearRect(0, 0, canvas.width, canvas.height);
        ctx.beginPath();
        ctx.arc(canvas.width / 2, canvas.height / 2, radius, 0, 2 * Math.PI);
        ctx.stroke();

        const x = canvas.width / 2 + radius * Math.sin(angle);
        const y = canvas.height / 2 - radius * Math.cos(angle);
        ctx.beginPath();
        ctx.arc(x, y, 5, 0, 2 * Math.PI);
        ctx.stroke();

        requestAnimationFrame(() => {
          if (isReleased) {
            accelerate();
            drawPendulum();
          }
        });
      }

      function accelerate() {
        velocity += (angle * Math.PI / 180) * gravity / period;
        angle += velocity;

        if (Math.abs(angle) > 90) {
          angle = Math.sign(angle) * 90;
          velocity = 0;
        }
      }

